/** 
 * Returns true if there is already an output buffer pending. Otherwise attempts to dequeue an output buffer and returns whether there is a new output buffer.
 */
private boolean maybeDequeueOutputBuffer(){
  if (outputBufferIndex >= 0) {
    return true;
  }
  if (outputStreamEnded) {
    return false;
  }
  try {
    outputBufferIndex=mediaCodec.dequeueOutputBuffer(outputBufferInfo,0);
  } catch (IllegalStateException e) {
    Log.e("MediaCodec", "dequeueOutputBuffer failed", e);
    return false;
  }
  if (outputBufferIndex < 0) {
    if (outputBufferIndex == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED) {
      try {
        outputFormat=getFormat(mediaCodec.getOutputFormat());
      } catch (IllegalStateException e) {
        Log.e("MediaCodec", "getOutputFormat failed", e);
        return false;
      }
    }
    return false;
  }
  if ((outputBufferInfo.flags & MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0) {
    outputStreamEnded=true;
    if (outputBufferInfo.size == 0) {
      releaseOutputBuffer();
      return false;
    }
  }
  if ((outputBufferInfo.flags & MediaCodec.BUFFER_FLAG_CODEC_CONFIG) != 0) {
    releaseOutputBuffer();
    return false;
  }
  return true;
}
